svg.script:
var light = false;

function showMessage(message) {
    var popup = document.getElementById("popup");
    var text = document.getElementById("popupText");

    text.textContent = message;

    popup.setAttribute("opacity", "1");
    popup.setAttribute("pointer-events", "all");
}

function hideMessage() {
    var popup = document.getElementById("popup");

    popup.setAttribute("opacity", "0");
    popup.setAttribute("pointer-events", "none");
}

function toggleTheme() {

    light = !light;

    var bg = document.querySelector("svg > rect");

    var icon = document.getElementById("themeIcon");

    if (light) {

        bg.setAttribute("fill", "#f3f4f7");

        icon.textContent = "☀";

    } else {

        bg.setAttribute("fill", "url(#background)");

        icon.textContent = "☾";

    }
}

function showSection(name) {

    if (name === "products") {
        document.getElementById("products")
            .scrollIntoView({behavior:"smooth"});
    }

    if (name === "features") {
        document.getElementById("features")
            .scrollIntoView({behavior:"smooth"});
    }

    if (name === "home") {
        document.getElementById("home")
            .scrollIntoView({behavior:"smooth"});
    }

    if (name === "community") {
        document.getElementById("products")
            .scrollIntoView({behavior:"smooth"});
    }
}

window.addEventListener("mousemove", function(e) {

    var svg = document.documentElement;

    var rect = svg.getBoundingClientRect();

    var x = (e.clientX - rect.left) / rect.width;
    var y = (e.clientY - rect.top) / rect.height;

    var shield = document.querySelector(".shield");

    if (shield) {

        shield.style.transform =
            "translate(" +
            ((x - .5) * 12) +
            "px," +
            ((y - .5) * 12) +
            "px)";

    }

});
